tests:
test({ sr: 'nalazi poziciju elementa', en: 'finds the position of an item' }, () => {
  expect(indexOfItem(['a', 'b', 'c'], 'b')).toBe(1);
});
test({ sr: 'element koga nema daje -1', en: 'an item that is missing gives -1' }, () => {
  expect(indexOfItem([1, 2, 3], 4)).toBe(-1);
});
test({ sr: 'prazan niz daje -1', en: 'an empty array gives -1' }, () => {
  expect(indexOfItem([], 1)).toBe(-1);
});

hiddenTests:
test('the first occurrence is returned', () => {
  expect(indexOfItem([5, 7, 5], 5)).toBe(0);
});
test('the last position is found too', () => {
  expect(indexOfItem([1, 2, 3], 3)).toBe(2);
});
test('the comparison is strict: the number 1 is not the string 1', () => {
  expect(indexOfItem(['1', 1], 1)).toBe(1);
  expect(indexOfItem([1, 2], '1')).toBe(-1);
});
test('does not change the input', () => {
  const input = [3, 1, 2];
  indexOfItem(input, 1);
  expect(input).toEqual([3, 1, 2]);
});

solutions.code:
function indexOfItem(items, target) {
  for (let i = 0; i < items.length; i++) {
    if (items[i] === target) return i;
  }
  return -1;
}
